#!/usr/bin/env python3
"""Assemble a factual gate from completed local test and science artifacts."""
import hashlib,json,re,subprocess
from pathlib import Path
import h5py,netCDF4,numpy,pyproj,shapely,xarray,zarr
from wave3_arrays import save
ROOT=Path(__file__).resolve().parents[1];WORK=ROOT/'prototype-output/wave4';DOC=ROOT/'docs/products/wave4'

def digest(path):return hashlib.sha256(path.read_bytes()).hexdigest()
def tests(log,command):
 p=WORK/log;s=p.read_text();assert 'FAILED' not in s and 'error: test failed' not in s and 'test result: ok.' in s,log
 rows=re.findall(r'test result: ok\. (\d+) passed; (\d+) failed; (\d+) ignored',s);counts=[sum(int(r[i]) for r in rows) for i in range(3)];assert counts[1]==0
 return dict(command=command,status='passed',passed=counts[0],failed=counts[1],ignored=counts[2],local_log=str(p.relative_to(ROOT)),log_sha256=digest(p))

def main():
 reports={name:json.loads((DOC/(name+'.json')).read_text()) for name in ['nisar-geographic-validation','nisar-additional-validation','smap-polar-validation','goes-validation','faults','live-native-validation','catalog-workflows','rust-workflows','performance','nisar-full-source-coordinate-oracle','smap-full-source-coordinate-oracle']}
 assert all(r['status']=='passed' for r in reports.values())
 binary=ROOT/'target/release/tile-ripper';assert reports['performance']['binary_sha256']==digest(binary)
 linux=(WORK/'linux-final.log').read_text();source_hashes={}
 for checksum,path in re.findall(r'^([a-f0-9]{64})  (.+)$',linux,re.M):source_hashes[path]=digest(ROOT/path)==checksum
 assert source_hashes and all(source_hashes.values()),source_hashes
 assert not re.search(r'lib(gdal|hdf5)',linux,re.I)
 versions={m.__name__:m.__version__ for m in [h5py,netCDF4,numpy,pyproj,shapely,xarray,zarr]}
 gate=dict(schema='tile-ripper-wave4-acceptance-v1',status='passed',date='2026-10-25',branch='codex/acquisition-planner',baseline='545a159',initial_implementation_commit='1aa2e3f',source_sha256={p:digest(ROOT/p) for p in source_hashes},binary_sha256=digest(binary),reference_versions=versions,rust_tests=[tests('all-features-serial-final.log','cargo test --locked --all-features --all-targets -- --test-threads=1'),tests('gdal-free-final.log','cargo test --locked --no-default-features --features native-cog,native-hdf5,authenticated-http -- --test-threads=1'),tests('hdf5-reader-tests.log','cargo test --locked --manifest-path vendor/hdf5-reader/Cargo.toml'),tests('linux-final.log','docker run rust:1.92-slim sh /source/bench/wave4_linux.sh')],science_cases=dict(nisar_geographic=len(reports['nisar-geographic-validation']['cases']),nisar_second_specimen=1,smap_polar=len(reports['smap-polar-validation']['cases']),goes_additional=len(reports['goes-validation']['cases']),inherited_wave3=19),fault_controls=len(reports['faults']['cases']),live_native_cases=len(reports['live-native-validation']['cases']),catalog_workflows=len(reports['catalog-workflows']['cases']),rust_workflows=len(reports['rust-workflows']['cases']),mature_workflow_comparisons=len(reports['performance']['cases']),coordinate_oracles=dict(nisar_all_centers=reports['nisar-full-source-coordinate-oracle']['evaluated_centers'],smap_all_centers=reports['smap-full-source-coordinate-oracle']['source_centers']),portability=dict(macos='ARM64 native release, all-feature/GDAL-free tests, clippy and dynamic linkage check',linux='fresh ARM64 ordinary-user release tests, final production/test source checksums match; no GDAL/libhdf5 linkage',unqualified=['Windows','minimum Rust toolchain']),additional_checks=dict(clippy='cargo clippy --locked --all-features --all-targets -- -D warnings',format='cargo fmt --all -- --check; git diff --check',python='py_compile five Wave4 Python harnesses',plan='dgov structural dry-run passed; dispatch-ready compilation unavailable because no provider is configured; work executed directly'),test_rerun_note='One parallel full-suite run returned Failed instead of Truncated in an unchanged SWOT CLI discovery control. The unchanged 16-test suite and final full suite passed serialized; no assertion or deadline was weakened.',remaining_unsupported=['other NISAR CRS/shapes/releases and channels, including candidate HVHV','complex covariance/RSLC/SLC','ABI full-disk/L1b and other bands/spacecraft','SMAP other releases/L4/southern grids','longitude-wrap, curvilinear/irregular grids and unqualified registration','reprojection/resampling/mosaics/composites','point/track products (next recommendation: bounded ATL06 v007)'],publication='no merge, push, tag, release, deploy, upstream patch or ChronoZarr change')
 save(DOC/'acceptance.json',gate)
 rows=['# Wave 4 measured workflow costs','','Fresh native and mature-reader processes use identical frozen guarded source bytes. Five one-shot comparisons cover both inspected NISAR grids, the new GOES layout, and both polar SMAP passes. Process times include startup/imports; native and mature selection/index work differ. These small AOIs do not establish throughput leadership.','','| Path | Included centers | Native end-to-end s | Mature end-to-end s | Native CPU s | Native peak RSS MiB | Native GET / HEAD | Source bytes | Physical decode / selected value bytes |','| --- | ---: | ---: | ---: | ---: | ---: | ---: | ---: | ---: |']
 for c in reports['performance']['cases']:
  events=c['native_source_events'];gets=sum(e['method']=='GET' for e in events);heads=sum(e['method']=='HEAD' for e in events);raw=sum(e['bytes'] for e in events if e['method']=='GET');n=c['native_process'];r=c['reference_process'];rows.append(f"| {c['family']} | {c['included_centers']} | {n['wall_seconds']:.4f} | {r['wall_seconds']:.4f} | {n['cpu_seconds']:.4f} | {n['peak_rss_bytes']/1048576:.2f} | {gets} / {heads} | {raw} | {c['decoded_to_selected_amplification']:.1f}× |")
 rows+=['','[Machine-readable measurements](performance.json) retain source request events, physical decoded/selected byte counts, grid inspection and selection time, physical planning, decode/delivery and durable output costs, first-chunk latency, CPU/RSS and working reservations for both workflows. [Live-native checks](live-native-validation.json) separately measure canonical provider access and authentication within preparation. [Catalog runs](catalog-workflows.json) report discovery and demonstrate automatic NISAR preparation from geographic bounds and polygon without supplied observations. Authentication has no separate isolated timer; it is included in live inspection/preparation, and the reports do not claim otherwise.','','Capture manifests count total bounded original bytes, including inherited seeded extents; they are not cold-provider performance measurements. Repeated comparison uses frozen replay and refuses uncaptured holes. Native payload reservations are admission bounds, not process-RSS limits. Mature Python imports/runtime are included in its process memory. The independent full-source NISAR coordinate sweep took about 122 s and ~155 MiB RSS; it is correctness evidence, not the mature benchmark algorithm.','','The same-grid mature workflows preserve raw values and separate masks and validate source identity before/after output. Native performs full restricted-index validation and richer product/calibration checks; mature HDF5-C may traverse fewer index nodes. Both flush data/directories and use macOS device-flush barriers before/after publication in fresh benchmark namespaces. The native writer retains its no-replace transactional semantics. No paid cloud service or provider-throughput test was used.']
 (DOC/'performance.md').write_text('\n'.join(rows)+'\n');print(json.dumps(dict(status='passed',rust_tests=[r['passed'] for r in gate['rust_tests']],science_cases=gate['science_cases'],fault_controls=gate['fault_controls'])))

if __name__=='__main__':main()
